/* ══════════════════════════════════════════════════════════
   pi-web styles
   ══════════════════════════════════════════════════════════ */

/* ── 基础 Reset（08-25 评审 P0：此前无 reset，原生 UA 按钮白块遍布全屏）── */
*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; }
html { -webkit-text-size-adjust: 100%; }
/* 暗色为默认主题（deep/ink/violet），mist 为浅色——让原生控件跟随 */
html { color-scheme: dark; }
html[data-theme="mist"] { color-scheme: light; }
html, body, #root { height: 100%; }
.mobile-app-root {
  height: 100vh;
  height: 100dvh;
  height: var(--pi-viewport-height);
}
body { line-height: 1.5; }
button {
  appearance: none;
  -webkit-appearance: none;
  background: transparent;
  border: 0;
  padding: 0;
  font: inherit;
  color: inherit;
  cursor: pointer;
}
button:disabled { cursor: default; }
input, select, textarea { font: inherit; color: inherit; }
img, svg, video, audio { max-width: 100%; }
img, svg, video { display: block; }
ul[class], ol[class] { list-style: none; margin: 0; padding: 0; }

/* @generated-tokens:start —— 本区块由 scripts/generate-theme.mjs 生成，勿手改 */
:root {
  --pi-bg: #0e1116;
  --pi-bg1: #181b20;
  --pi-bg2: #22252a;
  --pi-bg3: #2c2f35;
  --pi-bg4: #373a40;
  --pi-bg-hover: #1d2126;
  --pi-bg-active: #25282e;
  --pi-border: #282b31;
