  --pi-border-hi: rgba(255,255,255,0.10);
  --pi-text: #e8eef8;
  --pi-dim: #8891a1;
  --pi-dim2: #929cab;
  --pi-accent: #5468ff;
  --pi-accent2: #758eff;
  --pi-accent-deep: #3e4adf;
  --pi-accent-glow: rgba(84,104,255,0.35);
  --pi-glow: rgba(84,104,255,0.35);
  --pi-green: #3ecf8e;
  --pi-red: #f47067;
  --pi-yellow: #f5b759;
  --pi-glow-purple: rgba(139,92,246,0.18);
  --pi-glow-cyan: rgba(56,189,248,0.10);
  --pi-surface: #181b20;
  --pi-surface-fg: #e8eef8;
  --pi-overlay: #22252a;
  --pi-overlay-fg: #8891a1;
  --pi-field: #181b20;
  --pi-field-border: #1b1e24;
  --pi-default: #2c2f35;
  --pi-success: #3ecf8e;
  --pi-warning: #f5b759;
  --pi-danger: #f47067;
  --pi-accent-soft: rgba(84,104,255,0.12);
  --pi-accent-soft-fg: #5468ff;
  --pi-shadow-sm: rgba(0,0,0,0.18);
  --pi-shadow-md: rgba(0,0,0,0.26);
  --pi-shadow-lg: rgba(0,0,0,0.34);
  --pi-font-mono: "Cascadia Code", "JetBrains Mono", Consolas, "SF Mono", monospace;
  --pi-font-sans: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --pi-font-display: "Space Grotesk", "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --pi-radius-base: 6px;
  --pi-r-sm: 4px;
  --pi-r-md: 6px;
