  --pi-lh-sm: 1.333;
  --pi-fs-md: 13px;
  --pi-lh-md: 1.308;
  --pi-fs-lg: 15px;
  --pi-lh-lg: 1.267;
  --pi-fs-xl: 17px;
  --pi-lh-xl: 1.235;
  --pi-fs-xxl: 22px;
  --pi-lh-xxl: 1.182;
  --pi-accent-hover: #6982ff;
  --pi-accent-active: #4a5bf1;
  --pi-accent-muted: rgba(84,104,255,0.55);
  --pi-grad-accent: linear-gradient(135deg, #5468ff 0%, #758eff 100%);
  --pi-grad-glow: linear-gradient(135deg, #5468ff 0%, transparent 70%);
  --pi-btn-bg: #2c2f35;
  --pi-btn-border: #282b31;
  --pi-btn-hover: #1d2126;
  --pi-card-bg: #181b20;
  --pi-card-border: #282b31;
  --pi-input-bg: #181b20;
  --pi-input-border: #1b1e24;
  --pi-panel-bg: #181b20;
  --pi-panel-border: #282b31;
  --pi-dialog-bg: #22252a;
  --pi-dialog-border: #282b31;
  --pi-badge-bg: rgba(84,104,255,0.12);
  --pi-badge-fg: #5468ff;
  --pi-badge-border: transparent;
